// Build email fields + PDF binaries from the app's payload.
// n8n's webhook node nests the POST body under $json.body.
const j = $json.body || $json;
const f = j.files || {};
// Turn the plain-text cover-letter body into simple, well-spaced HTML.
function textToHtml(text) {
  const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const paras = esc(text).trim().split(/\n{2,}/).map((p) => '<p style="margin:0 0 12px">' + p.replace(/\n/g, '<br>') + '</p>').join('');
  return '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.5;color:#222">' + paras + '</div>';
}
const out = {
  json: {
    date: new Date().toISOString().slice(0, 10),
    type: j.type || 'job_application',
    source: j.source || '',
    company: j.company || '',
    title: j.title || '',
    location: j.location || '',
    contact_email: j.contact_email || '',
    apply_url: j.apply_url || '',
    subject: (j.email || {}).subject || `Application: ${j.title || ''}`,
    body: (j.email || {}).body || '',
    html: textToHtml((j.email || {}).body || ''),
    folder: j.folder || '',
    status: (j.type === 'followup') ? 'followup' : 'sent',
    applied: (j.type === 'followup') ? '' : 'yes'
  },
  binary: {}
};
if (f.resume && f.resume.content_base64) {
  out.binary.resume = { data: f.resume.content_base64, mimeType: 'application/pdf', fileName: f.resume.filename || 'resume.pdf' };
}
if (f.cover_letter && f.cover_letter.content_base64) {
  out.binary.cover = { data: f.cover_letter.content_base64, mimeType: 'application/pdf', fileName: f.cover_letter.filename || 'cover.pdf' };
}
return [out];
